'use strict';

// Checks the wedge and hash bonds the depiction draws by reading them back.
// For every specified stereocentre in the reference library, the drawing is
// re-interpreted with the ordinary convention (wedge towards the viewer, hash
// away, every other neighbour in the plane) and the configuration that reading
// implies is compared with the one the SMILES states. The reader here is
// separate code from the writer in js/stereo.js, so a sign error shows up.
// Generated report: data/wedgecases.js. Do not edit that by hand.

const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
function load(file) {
  const exports = require(path.join(root, file));
  Object.keys(exports).forEach((key) => { global[key] = exports[key]; });
  return exports;
}

load('js/smiles.js');
load('js/mol.js');
load('js/smarts.js');
load('js/descriptors.js');
load('js/stereo.js');
load('js/depict.js');
const LONE = -1;
const source = process.argv.find((arg) => /\.(txt|smi)$/.test(arg));
const rows = source
  ? fs.readFileSync(source, 'utf8').split('\n').map((line) => line.trim())
      .filter((line) => line.length).map((line, i) => ({ name: 'case ' + (i + 1), smiles: line }))
  : require(path.join(root, 'data/library.js')).LIBRARY;

function readBack(mol, coords, center, wedge) {
  const id = center.atom;
  const slots = center.neighbours;
  const real = slots.filter((slot) => slot !== null && slot !== LONE);
  const angles = real.map((slot) => Math.atan2(coords[slot].y - coords[id].y, coords[slot].x - coords[id].x));
  const sorted = angles.slice().sort((a, b) => a - b);
  let free = sorted.length ? sorted[0] + Math.PI : 0;
  let span = -1;
  for (let i = 0; i < sorted.length; i += 1) {
    const next = i + 1 < sorted.length ? sorted[i + 1] : sorted[0] + Math.PI * 2;
    if (next - sorted[i] > span) { span = next - sorted[i]; free = (sorted[i] + next) / 2; }
  }
  const place = (slot) => {
    if (slot === null || slot === LONE) {
      return { x: Math.cos(free), y: Math.sin(free), z: 0 };
    }
    const z = slot === wedge.to ? (wedge.type === 'wedge' ? 1 : -1) : 0;
    return { x: coords[slot].x - coords[id].x, y: coords[slot].y - coords[id].y, z: z };
  };
  const p = slots.map(place);
  const v = [1, 2, 3].map((i) => ({ x: p[i].x - p[0].x, y: p[i].y - p[0].y, z: p[i].z - p[0].z }));
  const cross = {
    x: v[1].y * v[2].z - v[1].z * v[2].y,
    y: v[1].z * v[2].x - v[1].x * v[2].z,
    z: v[1].x * v[2].y - v[1].y * v[2].x
  };
  const triple = v[0].x * cross.x + v[0].y * cross.y + v[0].z * cross.z;
  if (Math.abs(triple) < 1e-9) return null;
  return triple < 0 ? '@' : '@@';
}

let centers = 0;
let drawn = 0;
let agree = 0;
let undecided = 0;
const misses = [];

rows.forEach((row) => {
  const smiles = row.smiles;
  const name = row.name;
  let mol;
  try {
    mol = moleculeFromSmiles(smiles);
  } catch (err) {
    return;
  }
  const coords = depictCoordinates(mol);
  const wedges = stereoWedges(mol, coords);
  const byAtom = new Map();
  wedges.forEach((item) => byAtom.set(item.from, item));
  stereoTetrahedral(mol).forEach((center) => {
    if (!center.tag) return;
    centers += 1;
    const wedge = byAtom.get(center.atom);
    if (!wedge) return;
    drawn += 1;
    const read = readBack(mol, coords, center, wedge);
    if (read === null) { undecided += 1; return; }
    if (read === center.tag) agree += 1;
    else misses.push(name + ' atom ' + (center.atom + 1) + ' drawn ' + wedge.type
      + ', reads ' + read + ' but the SMILES says ' + center.tag);
  });
});

const report = {
  generated: new Date().toISOString().slice(0, 10),
  source: source ? 'enumerated stereoisomers of the reference library' : 'the reference library as written',
  compounds: rows.length,
  centers: centers,
  drawn: drawn,
  drawnPct: centers ? Math.round((drawn / centers) * 1000) / 10 : 0,
  agree: agree,
  agreePct: drawn ? Math.round((agree / drawn) * 10000) / 100 : 0,
  undecided: undecided,
  wrong: misses.length
};

console.log('specified stereocentres   ' + centers);
console.log('  carry a wedge or hash   ' + drawn + ' ' + report.drawnPct + ' %');
console.log('  read back as drawn      ' + agree + ' ' + report.agreePct + ' %');
console.log('  geometry too flat       ' + undecided);
console.log('  read back inverted      ' + misses.length);
misses.slice(0, 10).forEach((line) => console.log('    ' + line));

if (process.argv.indexOf('--write') >= 0) {
  const out = '// Generated by tools/stereo-depiction.js. Do not edit by hand.\n'
    + "'use strict';\n\nconst WEDGE_CONFORMANCE = " + JSON.stringify(report, null, 2) + ';\n\n'
    + "if (typeof module !== 'undefined' && module.exports) {\n"
    + '  module.exports = { WEDGE_CONFORMANCE };\n}\n';
  fs.writeFileSync(path.join(root, 'data/wedgecases.js'), out);
  console.log('wrote data/wedgecases.js');
}
